// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
import { evolvePath } from "@remotion/paths";

// Library: @remotion/paths — native evolvePath for drawing the wavy timeline

const { fontFamily: interFamily } = loadInter();



export type TimelineProps = Record<string, any>;

const Timeline: React.FC<TimelineProps> = ({
  backgroundColor = "#041b36",
  transparentBackground = false,
  durationInSeconds = 4,
  lineColor = "#ffffff",
  markerOuterColor = "#ffffff",
  markerInnerColor = "#36d1b7",
  textColor = "#ffffff",
  timelineItems = [
    "TENANT SCREENING",
    "VACANCIES",
    "REPAIRS",
    "FURNISHING",
    "ALL EXPENSES"
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080; 
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout parameters
  const paddingX = width * 0.12;
  const usableWidth = width - paddingX * 2;
  const nodeCount = Math.max(2, timelineItems.length); // prevent division by 0
  const spacing = timelineItems.length > 1 ? usableWidth / (nodeCount - 1) : usableWidth;
  const baselineY = height * 0.5;

  const nodes = useMemo(() => {
    return timelineItems.map((item, i) => {
      return {
        id: i,
        label: item,
        x: paddingX + i * spacing,
        y: baselineY,
      };
    });
  }, [timelineItems, paddingX, spacing, baselineY]);

  // Construct the mathematically perfect wavy path
  const d = useMemo(() => {
    const startX = -width * 0.1;
    const endX = width * 1.1;
    const totalPathWidth = endX - startX;
    let path = `M ${startX.toFixed(2)} ${baselineY.toFixed(2)}`;
    
    const pointsCount = 200; // high resolution for smooth bezier-like appearance
    for (let i = 1; i <= pointsCount; i++) {
      const t = i / pointsCount;
      const x = startX + totalPathWidth * t;
      const localX = x - paddingX;
      // Sine wave that perfectly crosses 0 at every node (spacing acts as half-wavelength)
      const y = baselineY + Math.sin((localX / spacing) * Math.PI) * (20 * s);
      path += ` L ${x.toFixed(2)} ${y.toFixed(2)}`;
    }
    
    return path;
  }, [width, baselineY, s, paddingX, spacing]);

  // Timing parameters: draw completes 1 second before the end to allow for rest
  const drawDuration = Math.max(fps * 0.5, fps * (durationInSeconds - 1));
  const startX = -width * 0.1;
  const endX = width * 1.1;
  const totalPathWidth = endX - startX;

  const lineProgress = interpolate(frame, [0, drawDuration], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  const { strokeDasharray, strokeDashoffset } = evolvePath(lineProgress, d);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        style={{ position: "absolute", top: 0, left: 0, overflow: "visible", transition: "none" }}
      >
        {/* The wavy line */}
        <path
          d={d}
          fill="none"
          stroke={lineColor}
          strokeWidth={10 * s}
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeDasharray={strokeDasharray}
          strokeDashoffset={strokeDashoffset}
          style={{ transition: "none" }}
        />
        
        {/* Nodes and vertical stems */}
        {nodes.map((node, i) => {
          const nodeRatio = (node.x - startX) / totalPathWidth;
          const triggerFrame = drawDuration * nodeRatio;

          const entranceProgress = spring({
            fps,
            frame: frame - triggerFrame,
            config: { damping: 12, mass: 0.8 },
          });

          const stemLength = 50 * s;
          const currentStemLength = interpolate(entranceProgress, [0, 1], [0, stemLength]);

          return (
            <g key={`marker-${node.id}`} style={{ transition: "none" }}>
              {/* Stem drawn behind circles */}
              <line
                x1={node.x}
                y1={node.y}
                x2={node.x}
                y2={node.y + currentStemLength}
                stroke={lineColor}
                strokeWidth={4 * s}
                opacity={entranceProgress}
                style={{ transition: "none" }}
              />
              
              {/* Outer Ring */}
              <circle
                cx={node.x}
                cy={node.y}
                r={16 * s * entranceProgress}
                fill={markerOuterColor}
                style={{ transition: "none" }}
              />
              
              {/* Inner Circle */}
              <circle
                cx={node.x}
                cy={node.y}
                r={8 * s * entranceProgress}
                fill={markerInnerColor}
                style={{ transition: "none" }}
              />
            </g>
          );
        })}
      </svg>

      {/* HTML Text Overlays */}
      {nodes.map((node, i) => {
        const nodeRatio = (node.x - startX) / totalPathWidth;
        const triggerFrame = drawDuration * nodeRatio;
        
        // Dim when the next node starts entering
        const nextTriggerFrame = i < nodes.length - 1 
          ? drawDuration * ((nodes[i + 1].x - startX) / totalPathWidth)
          : drawDuration + fps * 60; // Never dim the final node

        const entranceProgress = spring({
          fps,
          frame: frame - triggerFrame,
          config: { damping: 14, mass: 0.8 },
        });

        const dimProgress = spring({
          fps,
          frame: frame - nextTriggerFrame,
          config: { damping: 14 },
        });

        const activeOpacity = interpolate(entranceProgress, [0, 1], [0, 1]);
        const finalOpacity = interpolate(dimProgress, [0, 1], [activeOpacity, activeOpacity * 0.5]);
        
        // Starts lower and smoothly rises into place
        const yOffset = interpolate(entranceProgress, [0, 1], [40 * s, 0]);
        const textContainerWidth = spacing * 1.4;

        return (
          <div
            key={`text-${node.id}`}
            style={{
              position: "absolute",
              left: node.x - (textContainerWidth / 2),
              top: node.y + (70 * s) + yOffset,
              width: textContainerWidth,
              textAlign: "center",
              opacity: finalOpacity,
              color: textColor,
              fontWeight: 800,
              fontSize: 26 * s,
              lineHeight: 1.15,
              letterSpacing: 1.5 * s,
              textTransform: "uppercase",
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              justifyContent: "flex-start",
              wordWrap: "break-word",
              overflowWrap: "break-word",
              transition: "none",
            }}
          >
            {node.label}
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

export default Timeline;